//! Replays tests/golden/vectors.json (generated by the Python reference).
use gravit_verifier_rs::{verify, Epistemic, Evidence};
use serde_json::Value;
use std::{fs, path::PathBuf};

fn golden(name: &str) -> Value {
    let p: PathBuf = [env!("CARGO_MANIFEST_DIR"), "..", "tests", "golden", name].iter().collect();
    serde_json::from_str(&fs::read_to_string(&p).unwrap_or_else(|e| panic!("{:?}: {}", p, e))).unwrap()
}

#[test]
fn reproduces_every_python_golden_vector() {
    let bindings = golden("bindings.json");
    let bindings = bindings.as_array().expect("bindings array");
    let vectors = golden("vectors.json");
    let vectors = vectors.as_array().expect("vectors array");
    assert!(!vectors.is_empty());
    let mut failures = Vec::new();
    for v in vectors {
        let name = v["name"].as_str().unwrap();
        let claimed = v["claimed_state"].as_str().map(|s| Epistemic::from_name(s).expect("known state"));
        let evidence: Vec<Evidence> = v["evidence"].as_array().unwrap().iter().map(Evidence::from_value).collect();
        let high_impact = v["context"]["high_impact"].as_bool().unwrap_or(false);
        let got = verify(bindings, claimed, &evidence, high_impact);
        if got != v["expected"] {
            failures.push(format!("{}\n  got:      {}\n  expected: {}", name, got, v["expected"]));
        }
    }
    assert!(failures.is_empty(), "{} vector(s) differ:\n{}", failures.len(), failures.join("\n"));
}
